using System;
using System.IO;
using System.Linq;
using System.Globalization;
using System.Collections.Generic;

namespace Overdrive {
 public class FrameResult {public string File;public int Frames;public double AverageFps,LowOnePercent,Frame99Ms,Seconds;public override string ToString(){return Frames.ToString("N0")+" frames   |   "+AverageFps.ToString("N1")+" avg FPS   |   "+LowOnePercent.ToString("N1")+" 1% low   |   "+Frame99Ms.ToString("N2")+" ms p99";}}
 public static class Benchmarks {
  public static List<string> Csv(string line){var fields=new List<string>();var b=new System.Text.StringBuilder();bool quoted=false;for(int i=0;i<line.Length;i++){char c=line[i];if(c=='"'){if(quoted&&i+1<line.Length&&line[i+1]=='"'){b.Append('"');i++;}else quoted=!quoted;}else if(c==','&&!quoted){fields.Add(b.ToString());b.Clear();}else b.Append(c);}if(quoted)throw new FormatException("Malformed quoted CSV row");fields.Add(b.ToString());return fields;}
  public static FrameResult Calculate(IEnumerable<double> values,string file){double[] frames=values.Where(x=>!double.IsNaN(x)&&!double.IsInfinity(x)&&x>0&&x<=10000).ToArray();if(frames.Length<10)throw new Exception("At least 10 valid frame intervals are required");double sum=frames.Sum();Array.Sort(frames);int slow=Math.Max(1,(int)Math.Ceiling(frames.Length*.01));return new FrameResult{File=file,Frames=frames.Length,AverageFps=1000*frames.Length/sum,LowOnePercent=1000/frames.Skip(frames.Length-slow).Average(),Frame99Ms=frames[Math.Max(0,(int)Math.Ceiling(frames.Length*.99)-1)],Seconds=sum/1000};}
  public static FrameResult Import(string file){using(var reader=new StreamReader(file)){string first=reader.ReadLine();if(first==null)throw new Exception("Empty CSV");var headers=Csv(first.TrimStart('\ufeff'));int col=-1;foreach(string allowed in new[]{"MsBetweenPresents","CPUFrameTime","FrameTimeMs"}){col=headers.FindIndex(x=>x.Trim().Equals(allowed,StringComparison.OrdinalIgnoreCase));if(col>=0)break;}if(col<0)throw new Exception("Expected PresentMon MsBetweenPresents / CPUFrameTime or FrameTimeMs column");int pid=headers.FindIndex(x=>x.Trim().Equals("ProcessID",StringComparison.OrdinalIgnoreCase));var ids=new HashSet<string>();var frames=new List<double>();string line;while((line=reader.ReadLine())!=null){if(string.IsNullOrWhiteSpace(line))continue;var row=Csv(line);if(pid>=0&&pid<row.Count)ids.Add(row[pid]);if(ids.Count>1)throw new Exception("CSV contains multiple processes. Export only the target game");double value;if(col<row.Count&&double.TryParse(row[col],NumberStyles.Float,CultureInfo.InvariantCulture,out value))frames.Add(value);if(frames.Count>2000000)throw new Exception("Capture exceeds 2 million frames; import a shorter test");}return Calculate(frames,file);}}
  public static string Compare(FrameResult baseline,FrameResult tuned){if(baseline==null||tuned==null)return "Import a baseline and a tuned capture from the same scene and settings.";double change=(tuned.AverageFps/baseline.AverageFps-1)*100;return "Observed average FPS: "+change.ToString("+0.0;-0.0;0.0")+"%   ·   Baseline "+baseline.AverageFps.ToString("N1")+" → tuned "+tuned.AverageFps.ToString("N1")+"\r\n"+"1% low: "+baseline.LowOnePercent.ToString("N1")+" → "+tuned.LowOnePercent.ToString("N1")+" FPS\r\nRepeat each capture several times. Different scenes, settings, warm-up or sample durations invalidate a direct comparison.";}
 }
}
